function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => v !== 0 && v !== 1)) return 'Each value of nums is 0 or 1.';
  return null;
}

