function minSwaps(nums) {
  const n = nums.length;
  let total = 0;
  for (const value of nums) {
    total += value;
  }
  let ones = 0;
  for (let i = 0; i < total; i++) {
    ones += nums[i];
  }
  let best = ones;
  for (let start = 1; start < n; start++) {
    ones += nums[(start + total - 1) % n];
    ones -= nums[start - 1];
    best = Math.max(best, ones);
  }
  return total - best;
}

