function minSwaps(nums) {
  // Breadth-first search over arrangements: each step swaps a 1 with a 0,
  // and the first arrangement reached whose ones form one circular run gives the answer.
  const n = nums.length;
  const grouped = mask => {
    let runs = 0;
    let count = 0;
    for (let i = 0; i < n; i++) {
      const here = (mask >> i) & 1;
      const before = (mask >> ((i - 1 + n) % n)) & 1;
      count += here;
      if (here && !before) runs++;
    }
    return count === 0 || count === n || runs === 1;
  };
  let start = 0;
  nums.forEach((v, i) => { if (v) start |= 1 << i; });
  const dist = new Map([[start, 0]]);
  const queue = [start];
  for (let head = 0; head < queue.length; head++) {
    const mask = queue[head];
    if (grouped(mask)) return dist.get(mask);
    for (let i = 0; i < n; i++) {
      if (!((mask >> i) & 1)) continue;
      for (let j = 0; j < n; j++) {
        if ((mask >> j) & 1) continue;
        const next = mask ^ (1 << i) ^ (1 << j);
        if (!dist.has(next)) { dist.set(next, dist.get(mask) + 1); queue.push(next); }
      }
    }
  }
  return -1;
}

