function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const density = [0, 0.1, 0.3, 0.5, 0.7, 0.9, 1][Math.floor(rand() * 7)];
  const pick = rand() < 0.15 ? density : rand();
  return [Array.from({ length: n }, () => (rand() < pick ? 1 : 0))];
}
